using System;
using System.IO;
using System.Text;
using UnityEngine;

namespace Game.Core.Navigation
{
    /// <summary>
    /// Routing graph of one region (KRTG v1/v2, generated by <c>tools/worldgen/navgraph/build_route_graph.py</c> from the
    /// region's road graph with provenance and the OSM turn restrictions; Resources/CabDisplay/Nav/&lt;region&gt;_route.bytes).
    /// v2 = v1 + per-edge truck limits (M21) + lane section (M22); version 1 files (no limits, no lanes) are still readable.
    /// M27: node flag bit1 / edge flag bit6 mark the parts the truck cannot drive to from the main strongly connected
    /// component of the directed graph ("poza zasięgiem", ADR 0150) - plain flag bits, present in v1 and v2 files alike.
    /// Region-local metres (x = east, y = north, ADR 0003). Loaded once; queries read flat arrays only (no allocation).
    /// Directed edge id = edge * 2 + dir (dir 0: from -> to, 1: to -> from). One-way edges have only dir 0.
    /// Data: OpenStreetMap contributors (ODbL 1.0) - docs/LICENSES.md.
    /// </summary>
    public sealed class RouteGraph
    {
        public const string ResourceFolder = "CabDisplay/Nav/";
        public const string ResourceSuffix = "_route";

        public const byte FlagOneway = 1, FlagRoundabout = 2, FlagNoTruck = 4, FlagRestricted = 8, FlagLink = 16, FlagHgvDestination = 32;
        /// <summary>Edge flag bit6 (M27): the edge cannot be entered from the main strongly connected component in any
        /// allowed direction (the region clip cut the only connection, ADR 0150) - "poza zasięgiem"; not a destination.</summary>
        public const byte FlagOffReach = 64;
        /// <summary>Node flag bit0 = boundary (edge leaves the region data), bit1 (M27) = off-reach (no directed path to
        /// the node from the main strongly connected component).</summary>
        public const byte FlagNodeBoundary = 1, FlagNodeOffReach = 2;

        // Lane direction bits (OSM Key:turn:lanes, generator KRTG v2): one u8 mask per lane, leftmost lane first.
        public const byte LaneLeft = 1, LaneSlightLeft = 2, LaneThrough = 4, LaneSlightRight = 8, LaneRight = 16,
            LaneMergeToLeft = 32, LaneMergeToRight = 64, LaneReverse = 128;

        public string[] Names = Array.Empty<string>();
        public Vector2[] NodePos = Array.Empty<Vector2>();
        public byte[] NodeFlags = Array.Empty<byte>();

        public int[] EdgeFrom = Array.Empty<int>(), EdgeTo = Array.Empty<int>();
        public float[] EdgeLength = Array.Empty<float>();
        public byte[] EdgeClass = Array.Empty<byte>(), EdgeFlags = Array.Empty<byte>();
        public ushort[] EdgeName = Array.Empty<ushort>();
        /// <summary>Speed limit [km/h], 0 = unknown.</summary>
        public byte[] EdgeMaxSpeed = Array.Empty<byte>();
        /// <summary>True when the limit is tagged in OSM (false: pipeline default, UNVERIFIED - not shown as a sign).</summary>
        public bool[] EdgeMaxSpeedOsm = Array.Empty<bool>();
        /// <summary>Format version of the loaded file (1 = no limit fields, 2 = with the four arrays below).</summary>
        public int Version = 1;
        /// <summary>Max total weight [0.01 t], 0 = no limit (OSM maxweight:hgv / maxweight; KRTG v2).</summary>
        public ushort[] EdgeMaxWeightC = Array.Empty<ushort>();
        /// <summary>Max axle load [0.01 t], 0 = no limit (OSM maxaxleload; KRTG v2).</summary>
        public ushort[] EdgeMaxAxleLoadC = Array.Empty<ushort>();
        /// <summary>Max height [cm], 0 = no limit (OSM maxheight; KRTG v2).</summary>
        public ushort[] EdgeMaxHeightCm = Array.Empty<ushort>();
        /// <summary>Max vehicle length [cm], 0 = no limit (OSM maxlength; KRTG v2).</summary>
        public ushort[] EdgeMaxLengthCm = Array.Empty<ushort>();
        /// <summary>Polyline of edge i spans Points[EdgeStart[i] .. EdgeStart[i + 1]) from EdgeFrom to EdgeTo.</summary>
        public int[] EdgeStart = Array.Empty<int>();
        public Vector2[] Points = Array.Empty<Vector2>();
        /// <summary>Cumulative distance along the edge at each point.</summary>
        public float[] PointS = Array.Empty<float>();
        public Vector4[] EdgeBounds = Array.Empty<Vector4>();

        // Outgoing directed edges per node (CSR).
        public int[] OutStart = Array.Empty<int>();
        public int[] OutDirected = Array.Empty<int>();

        // Turn restrictions (OSM relations).
        public int[] RestrFrom = Array.Empty<int>(), RestrVia = Array.Empty<int>(), RestrTo = Array.Empty<int>();
        public byte[] RestrKind = Array.Empty<byte>();   // 0 no_*, 1 only_*

        // Lane data (KRTG v2; v1 files and graphs built in code: all counts 0).
        /// <summary>Lane count of edge i in the stored forward direction (from -> to, after any oneway=-1 reversal).</summary>
        public byte[] EdgeLanesFwd = Array.Empty<byte>();
        /// <summary>Lane count in the backward direction (0 on one-way edges - never driven).</summary>
        public byte[] EdgeLanesBwd = Array.Empty<byte>();
        /// <summary>Per edge: start of its lane masks in <see cref="EdgeLaneMask"/> (fwd masks first, then bwd).</summary>
        public int[] EdgeLaneStart = Array.Empty<int>();
        public byte[] EdgeLaneMask = Array.Empty<byte>();

        public int LaneCount(int edge, bool reversed) => reversed ? EdgeLanesBwd[edge] : EdgeLanesFwd[edge];
        public byte LaneMask(int edge, bool reversed, int lane)
        {
            int s = EdgeLaneStart[edge] + (reversed ? EdgeLanesFwd[edge] : 0);
            return s + lane < EdgeLaneStart[edge + 1] ? EdgeLaneMask[s + lane] : (byte)0;
        }

        /// <summary>Builds <see cref="EdgeLaneStart"/> / <see cref="EdgeLaneMask"/> from per-edge lane masks (load and tests).</summary>
        public void BuildLaneIndex(byte[][] fwdMasks, byte[][] bwdMasks)
        {
            int n = EdgeFrom.Length;
            EdgeLanesFwd = new byte[n]; EdgeLanesBwd = new byte[n]; EdgeLaneStart = new int[n + 1];
            int total = 0;
            for (int e = 0; e < n; e++)
            {
                EdgeLanesFwd[e] = (byte)(fwdMasks != null && fwdMasks[e] != null ? fwdMasks[e].Length : 0);
                EdgeLanesBwd[e] = (byte)(bwdMasks != null && bwdMasks[e] != null ? bwdMasks[e].Length : 0);
                EdgeLaneStart[e] = total; total += EdgeLanesFwd[e] + EdgeLanesBwd[e];
            }
            EdgeLaneStart[n] = total;
            EdgeLaneMask = new byte[total];
            for (int e = 0; e < n; e++)
            {
                int s = EdgeLaneStart[e];
                if (fwdMasks != null && fwdMasks[e] != null) for (int i = 0; i < fwdMasks[e].Length; i++) EdgeLaneMask[s + i] = fwdMasks[e][i];
                if (bwdMasks != null && bwdMasks[e] != null) for (int i = 0; i < bwdMasks[e].Length; i++) EdgeLaneMask[s + EdgeLanesFwd[e] + i] = bwdMasks[e][i];
            }
        }

        public Vector2 Min, Max;

        public int NodeCount => NodePos.Length;
        public int EdgeCount => EdgeFrom.Length;
        public int DirectedCount => EdgeFrom.Length * 2;

        public static RouteGraph Load(string regionId)
        {
            if (string.IsNullOrEmpty(regionId)) return null;
            var ta = Resources.Load<TextAsset>(ResourceFolder + regionId + ResourceSuffix);
            if (ta == null) return null;
            try { return Parse(ta.bytes); }
            finally { Resources.UnloadAsset(ta); }
        }

        public static RouteGraph Parse(byte[] bytes)
        {
            using var ms = new MemoryStream(bytes, false);
            using var r = new BinaryReader(ms, Encoding.UTF8);
            if (r.ReadByte() != 'K' || r.ReadByte() != 'R' || r.ReadByte() != 'T' || r.ReadByte() != 'G') throw new FormatException("not a KRTG file");
            int version = r.ReadUInt16();
            if (version != 1 && version != 2) throw new FormatException("KRTG version " + version + " unsupported");
            var g = new RouteGraph();
            g.Version = version;
            int nNames = r.ReadUInt16();
            g.Names = new string[nNames];
            for (int i = 0; i < nNames; i++) g.Names[i] = Encoding.UTF8.GetString(r.ReadBytes(r.ReadUInt16()));

            int nNodes = (int)r.ReadUInt32();
            g.NodePos = new Vector2[nNodes]; g.NodeFlags = new byte[nNodes];
            for (int i = 0; i < nNodes; i++) { g.NodePos[i] = new Vector2(r.ReadSingle(), r.ReadSingle()); g.NodeFlags[i] = r.ReadByte(); }

            int nE = (int)r.ReadUInt32();
            g.EdgeFrom = new int[nE]; g.EdgeTo = new int[nE]; g.EdgeLength = new float[nE]; g.EdgeClass = new byte[nE];
            g.EdgeFlags = new byte[nE]; g.EdgeName = new ushort[nE]; g.EdgeMaxSpeed = new byte[nE]; g.EdgeMaxSpeedOsm = new bool[nE];
            g.EdgeMaxWeightC = new ushort[nE]; g.EdgeMaxAxleLoadC = new ushort[nE];
            g.EdgeMaxHeightCm = new ushort[nE]; g.EdgeMaxLengthCm = new ushort[nE];
            g.EdgeStart = new int[nE + 1]; g.EdgeBounds = new Vector4[nE];
            var pts = new System.Collections.Generic.List<Vector2>(8192);
            var ps = new System.Collections.Generic.List<float>(8192);
            Vector2 lo = new Vector2(float.MaxValue, float.MaxValue), hi = new Vector2(float.MinValue, float.MinValue);
            for (int i = 0; i < nE; i++)
            {
                g.EdgeFrom[i] = (int)r.ReadUInt32(); g.EdgeTo[i] = (int)r.ReadUInt32();
                if (g.EdgeFrom[i] >= nNodes || g.EdgeTo[i] >= nNodes) throw new FormatException("edge node out of range");
                g.EdgeLength[i] = r.ReadSingle(); g.EdgeClass[i] = r.ReadByte(); g.EdgeFlags[i] = r.ReadByte();
                g.EdgeName[i] = r.ReadUInt16(); g.EdgeMaxSpeed[i] = r.ReadByte(); g.EdgeMaxSpeedOsm[i] = r.ReadByte() == 1;
                if (g.EdgeName[i] >= nNames) throw new FormatException("edge name out of range");
                int n = r.ReadUInt16();
                if (version >= 2)
                {
                    g.EdgeMaxWeightC[i] = r.ReadUInt16(); g.EdgeMaxAxleLoadC[i] = r.ReadUInt16();
                    g.EdgeMaxHeightCm[i] = r.ReadUInt16(); g.EdgeMaxLengthCm[i] = r.ReadUInt16();
                }
                if (n < 2) throw new FormatException("edge with < 2 points");
                g.EdgeStart[i] = pts.Count;
                var b = new Vector4(float.MaxValue, float.MaxValue, float.MinValue, float.MinValue);
                float s = 0f;
                for (int k = 0; k < n; k++)
                {
                    var p = new Vector2(r.ReadSingle(), r.ReadSingle());
                    if (k > 0) s += Vector2.Distance(pts[pts.Count - 1], p);
                    pts.Add(p); ps.Add(s);
                    b = new Vector4(Mathf.Min(b.x, p.x), Mathf.Min(b.y, p.y), Mathf.Max(b.z, p.x), Mathf.Max(b.w, p.y));
                }
                g.EdgeBounds[i] = b;
                lo = Vector2.Min(lo, new Vector2(b.x, b.y)); hi = Vector2.Max(hi, new Vector2(b.z, b.w));
            }
            g.EdgeStart[nE] = pts.Count;
            g.Points = pts.ToArray(); g.PointS = ps.ToArray();
            g.Min = lo; g.Max = hi;

            int nR = r.ReadUInt16();
            g.RestrFrom = new int[nR]; g.RestrVia = new int[nR]; g.RestrTo = new int[nR]; g.RestrKind = new byte[nR];
            for (int i = 0; i < nR; i++)
            {
                g.RestrFrom[i] = (int)r.ReadUInt32(); g.RestrVia[i] = (int)r.ReadUInt32(); g.RestrTo[i] = (int)r.ReadUInt32(); g.RestrKind[i] = r.ReadByte();
            }
            if (version >= 2)
            {
                // Lane blocks: u32 edge, u8 nFwd, u8 nBwd, then nFwd + nBwd lane masks (fwd first).
                int nL = (int)r.ReadUInt32();
                var fwd = new byte[nE][]; var bwd = new byte[nE][];
                for (int i = 0; i < nL; i++)
                {
                    int ei = (int)r.ReadUInt32();
                    if (ei >= nE) throw new FormatException("lane block edge out of range");
                    int nf = r.ReadByte(), nb = r.ReadByte();
                    fwd[ei] = new byte[nf]; bwd[ei] = new byte[nb];
                    for (int k = 0; k < nf; k++) fwd[ei][k] = r.ReadByte();
                    for (int k = 0; k < nb; k++) bwd[ei][k] = r.ReadByte();
                }
                g.BuildLaneIndex(fwd, bwd);
            }
            else
            {
                g.EdgeLanesFwd = new byte[nE]; g.EdgeLanesBwd = new byte[nE];
                g.EdgeLaneStart = new int[nE + 1]; g.EdgeLaneMask = Array.Empty<byte>();
            }
            if (ms.Position != ms.Length) throw new FormatException("KRTG trailing bytes");
            g.BuildAdjacency();
            return g;
        }

        /// <summary>Builds the outgoing directed-edge lists from the edge tables (also used by tests that build graphs in code).</summary>
        public void BuildAdjacency()
        {
            int n = NodePos.Length;
            var count = new int[n + 1];
            for (int e = 0; e < EdgeFrom.Length; e++)
            {
                count[EdgeFrom[e]]++;
                if ((EdgeFlags[e] & FlagOneway) == 0) count[EdgeTo[e]]++;
            }
            OutStart = new int[n + 1];
            for (int i = 0; i < n; i++) OutStart[i + 1] = OutStart[i] + count[i];
            OutDirected = new int[OutStart[n]];
            var fill = new int[n];
            for (int e = 0; e < EdgeFrom.Length; e++)
            {
                int a = EdgeFrom[e];
                OutDirected[OutStart[a] + fill[a]++] = e * 2;
                if ((EdgeFlags[e] & FlagOneway) == 0) { int b = EdgeTo[e]; OutDirected[OutStart[b] + fill[b]++] = e * 2 + 1; }
            }
            // Optional v2 per-edge tables (truck limits, lanes): graphs built in code or from v1 files get "none" so the
            // planner can index them without checks (0 = no limit, 0 lanes).
            int ne = EdgeFrom.Length;
            if (EdgeMaxWeightC.Length != ne) EdgeMaxWeightC = new ushort[ne];
            if (EdgeMaxAxleLoadC.Length != ne) EdgeMaxAxleLoadC = new ushort[ne];
            if (EdgeMaxHeightCm.Length != ne) EdgeMaxHeightCm = new ushort[ne];
            if (EdgeMaxLengthCm.Length != ne) EdgeMaxLengthCm = new ushort[ne];
            if (EdgeLanesFwd.Length != ne || EdgeLanesBwd.Length != ne || EdgeLaneStart.Length != ne + 1)
            {
                EdgeLanesFwd = new byte[ne]; EdgeLanesBwd = new byte[ne]; EdgeLaneStart = new int[ne + 1]; EdgeLaneMask = Array.Empty<byte>();
            }
            if (PointS.Length != Points.Length)
            {
                PointS = new float[Points.Length];
                for (int e = 0; e < EdgeFrom.Length; e++)
                    for (int k = EdgeStart[e] + 1; k < EdgeStart[e + 1]; k++) PointS[k] = PointS[k - 1] + Vector2.Distance(Points[k - 1], Points[k]);
            }
            if (EdgeBounds.Length != EdgeFrom.Length)
            {
                EdgeBounds = new Vector4[EdgeFrom.Length];
                for (int e = 0; e < EdgeFrom.Length; e++)
                {
                    var b = new Vector4(float.MaxValue, float.MaxValue, float.MinValue, float.MinValue);
                    for (int k = EdgeStart[e]; k < EdgeStart[e + 1]; k++)
                        b = new Vector4(Mathf.Min(b.x, Points[k].x), Mathf.Min(b.y, Points[k].y), Mathf.Max(b.z, Points[k].x), Mathf.Max(b.w, Points[k].y));
                    EdgeBounds[e] = b;
                }
            }
        }

        public static int EdgeOf(int directed) => directed >> 1;
        public static bool Reversed(int directed) => (directed & 1) != 0;
        public int StartNode(int directed) => Reversed(directed) ? EdgeTo[directed >> 1] : EdgeFrom[directed >> 1];
        public int EndNode(int directed) => Reversed(directed) ? EdgeFrom[directed >> 1] : EdgeTo[directed >> 1];
        public bool IsOneway(int edge) => (EdgeFlags[edge] & FlagOneway) != 0;
        public bool IsRoundabout(int edge) => (EdgeFlags[edge] & FlagRoundabout) != 0;
        /// <summary>True when the node cannot be driven to from the main component ("poza zasięgiem", M27 flag;
        /// graphs without the flags - older .bytes - report every node as reachable).</summary>
        public bool NodeOffReach(int node) => (NodeFlags[node] & FlagNodeOffReach) != 0;
        /// <summary>True when the edge cannot be entered from the main component (M27 flag; see <see cref="NodeOffReach"/>).</summary>
        public bool EdgeOffReach(int edge) => (EdgeFlags[edge] & FlagOffReach) != 0;
        public string NameOf(int edge) => Names[EdgeName[edge]];

        /// <summary>Nearest node of the main reachable component to <paramref name="p"/> (-1 when every node is
        /// off-reach). Brute force, taps only. Used to snap a destination tapped in an off-reach part.</summary>
        public int NearestMainNode(Vector2 p)
        {
            int best = -1;
            float best2 = float.MaxValue;
            for (int i = 0; i < NodePos.Length; i++)
            {
                if (NodeOffReach(i)) continue;
                float d2 = (NodePos[i] - p).sqrMagnitude;
                if (d2 < best2) { best2 = d2; best = i; }
            }
            return best;
        }

        /// <summary>Name of the first main-component edge leaving <paramref name="node"/> (0 = unnamed / none) -
        /// the street label of a pin snapped to a node.</summary>
        public ushort MainNameAt(int node)
        {
            for (int k = OutStart[node]; k < OutStart[node + 1]; k++)
            {
                int e = OutDirected[k] >> 1;
                if (!EdgeOffReach(e)) return EdgeName[e];
            }
            // End of a one-way spur (no outgoing edge): name of an incoming reachable edge (integration r5).
            for (int e = 0; e < EdgeTo.Length; e++)
                if ((EdgeTo[e] == node || EdgeFrom[e] == node) && !EdgeOffReach(e)) return EdgeName[e];
            return 0;
        }

        /// <summary>Point at distance <paramref name="s"/> from the start of the directed edge.</summary>
        public Vector2 PointAlong(int directed, float s)
        {
            int e = directed >> 1, a = EdgeStart[e], b = EdgeStart[e + 1] - 1;
            float len = PointS[b];
            float t = Reversed(directed) ? len - s : s;
            t = Mathf.Clamp(t, 0f, len);
            for (int k = a + 1; k <= b; k++)
                if (PointS[k] >= t)
                {
                    float seg = PointS[k] - PointS[k - 1];
                    return seg > 1e-6f ? Vector2.Lerp(Points[k - 1], Points[k], (t - PointS[k - 1]) / seg) : Points[k];
                }
            return Points[b];
        }

        /// <summary>Unit direction of the directed edge at distance <paramref name="s"/> from its start (over ±<paramref name="span"/> m).</summary>
        public Vector2 DirectionAt(int directed, float s, float span)
        {
            float len = EdgeLength[directed >> 1];
            float a = Mathf.Clamp(s - span, 0f, len), b = Mathf.Clamp(s + span, 0f, len);
            if (b - a < 1e-3f) { a = 0f; b = len; }
            Vector2 d = PointAlong(directed, b) - PointAlong(directed, a);
            float m = d.magnitude;
            return m > 1e-5f ? d / m : Vector2.up;
        }

        /// <summary>Polyline length of an edge (geometry; <see cref="EdgeLength"/> is the generator's value, equal within mm).</summary>
        public float GeomLength(int edge) => PointS[EdgeStart[edge + 1] - 1];

        /// <summary>
        /// Nearest edge to <paramref name="p"/> within <paramref name="maxDist"/> m. Returns the edge (-1 none), the distance
        /// along it from EdgeFrom and the projected point. Edges flagged no-truck are skipped when <paramref name="truckOnly"/>,
        /// off-reach edges (M27) when <paramref name="mainComponentOnly"/> (destination snap). Brute force over all segments
        /// with bounding-box culling: ~0.1 ms for this region, called on taps and reroutes only.
        /// </summary>
        public int Snap(Vector2 p, float maxDist, out float along, out Vector2 onEdge, out float dist, bool truckOnly = false,
            bool mainComponentOnly = false)
        {
            int best = -1; along = 0f; onEdge = p; dist = maxDist;
            float best2 = maxDist * maxDist;
            for (int e = 0; e < EdgeFrom.Length; e++)
            {
                if (truckOnly && (EdgeFlags[e] & FlagNoTruck) != 0) continue;
                if (mainComponentOnly && (EdgeFlags[e] & FlagOffReach) != 0) continue;
                var b = EdgeBounds[e];
                if (p.x < b.x - dist || p.x > b.z + dist || p.y < b.y - dist || p.y > b.w + dist) continue;
                for (int k = EdgeStart[e] + 1; k < EdgeStart[e + 1]; k++)
                {
                    Vector2 a = Points[k - 1], c = Points[k], ab = c - a;
                    float l2 = ab.sqrMagnitude;
                    float t = l2 > 1e-8f ? Mathf.Clamp01(Vector2.Dot(p - a, ab) / l2) : 0f;
                    Vector2 q = a + ab * t;
                    float d2 = (p - q).sqrMagnitude;
                    if (d2 < best2)
                    {
                        best2 = d2; best = e; onEdge = q; along = PointS[k - 1] + t * (PointS[k] - PointS[k - 1]);
                        dist = Mathf.Sqrt(d2);
                    }
                }
            }
            if (best < 0) dist = float.MaxValue;
            return best;
        }

        /// <summary>OSM turn restrictions: may a vehicle arriving on edge <paramref name="inEdge"/> at node <paramref name="via"/> leave on <paramref name="outEdge"/>?</summary>
        public bool TurnAllowed(int inEdge, int via, int outEdge)
        {
            bool hasOnly = false, onlyMatch = false;
            for (int i = 0; i < RestrFrom.Length; i++)
            {
                if (RestrFrom[i] != inEdge || RestrVia[i] != via) continue;
                if (RestrKind[i] == 0) { if (RestrTo[i] == outEdge) return false; }
                else { hasOnly = true; if (RestrTo[i] == outEdge) onlyMatch = true; }
            }
            return !hasOnly || onlyMatch;
        }

        /// <summary>Number of directed edges (any vehicle; a driver sees every road) that may be taken out of <paramref name="node"/> after arriving on <paramref name="inDirected"/>
        /// (U-turn onto the same edge excluded).</summary>
        public int ChoicesAt(int node, int inDirected)
        {
            int n = 0, inE = inDirected >> 1;
            for (int k = OutStart[node]; k < OutStart[node + 1]; k++)
            {
                int d = OutDirected[k], e = d >> 1;
                if (e == inE) continue;
                if (!TurnAllowed(inE, node, e)) continue;
                n++;
            }
            return n;
        }
    }
}
